<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{Archive,Plus,Save,Send,Trash2}from'@lucide/vue';import{getActivePinia}from'pinia';import{api,apiError,unpack}from'@/services/api';import type{Rubric,RubricCriterion}from'@/types';import StatusPill from'@/components/StatusPill.vue';import{useLocaleStore}from'@/stores/locale'
const locale=getActivePinia()?useLocaleStore():{t:(value:string)=>value},rubrics=ref<Rubric[]>([]),selectedId=ref(''),working=ref<Rubric|null>(null),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),savedSnapshot=ref('');const total=computed(()=>working.value?.criteria.reduce((n,c)=>n+Number(c.weight),0)||0),criteriaValid=computed(()=>!!working.value?.criteria.length&&working.value.criteria.every(c=>c.id.trim()&&c.name.trim())),dirty=computed(()=>!!working.value&&JSON.stringify(working.value)!==savedSnapshot.value),hasUnpublishedVersion=computed(()=>!!working.value&&(working.value.status==='draft'||working.value.version!==working.value.publishedVersion))
async function load(nextId?:string){rubrics.value=unpack(await api.getRubrics());const target=nextId??(selectedId.value!=='new'?selectedId.value:'')??rubrics.value[0]?.id;if(target&&rubrics.value.some(r=>r.id===target))select(target);else if(rubrics.value[0])select(rubrics.value[0].id)};function select(id:string){selectedId.value=id;const found=rubrics.value.find(r=>r.id===id);working.value=found?JSON.parse(JSON.stringify(found)) as Rubric:null;savedSnapshot.value=working.value?JSON.stringify(working.value):''}
function blankCriterion(weight=100){return{id:`criterion-${Date.now()}`,name:'New assessment domain',description:'',weight,anchors:[{score:0,label:'Not demonstrated',description:''},{score:1,label:'Emerging',description:''},{score:2,label:'Developing',description:''},{score:3,label:'Proficient',description:''}]}}
function createNew(){selectedId.value='new';working.value={id:'new',name:'New history-taking rubric',description:'',version:0,status:'draft',criteria:[blankCriterion()]};savedSnapshot.value=''}
function updateRedFlagIds(criterion:RubricCriterion,event:Event){criterion.redFlagIds=(event.target as HTMLInputElement).value.split(',').map(value=>value.trim()).filter(Boolean)}
onMounted(async()=>{try{await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}});function add(){working.value?.criteria.push(blankCriterion(0))}function remove(index:number){working.value?.criteria.splice(index,1)}async function save(){if(!working.value||total.value!==100)return;saving.value=true;error.value='';notice.value='';try{const saved=working.value.id==='new'?await api.createRubric(working.value):await api.updateRubric(working.value.id,working.value);selectedId.value=String(saved.id);await load(String(saved.id));notice.value=working.value?.version===1?'Rubric created.':'Rubric saved as a new version.'}catch(e){error.value=apiError(e)}finally{saving.value=false}}
async function changeStatus(action:'publish'|'archive'){if(!working.value||working.value.id==='new'||total.value!==100)return;saving.value=true;error.value='';try{await api.rubricAction(working.value.id,action);await load(working.value.id);notice.value=`Rubric ${action==='publish'?'published':'archived'} successfully.`}catch(e){error.value=apiError(e)}finally{saving.value=false}}
</script>
<template><div class="page"><header class="page-header"><div><div class="page-eyebrow">Assessment design</div><h1>Rubric editor</h1><p class="subtitle">Define observable, behaviour-anchored history-taking criteria. Weights must total 100%.</p></div><div class="rubric-actions"><button class="button button--secondary" @click="createNew"><Plus :size="16"/>New rubric</button><button v-if="working?.id!=='new'&&hasUnpublishedVersion" class="button button--secondary" :disabled="saving||total!==100||!criteriaValid||dirty" :title="dirty?'Save your changes before publishing':''" @click="changeStatus('publish')"><Send :size="16"/>{{working?.status==='published'?'Publish changes':'Publish'}}</button><button v-if="working?.status==='published'" class="button button--secondary" :disabled="saving||dirty" @click="changeStatus('archive')"><Archive :size="16"/>Archive</button><button class="button" :disabled="!working||saving||total!==100||!criteriaValid||!working.name.trim()||(!dirty&&working.id!=='new')" @click="save"><Save :size="16"/>{{working?.id==='new'?'Create rubric':'Save new version'}}</button></div></header><div v-if="error" class="alert alert--error">{{error}}</div><div v-if="notice" class="alert alert--success">{{notice}}</div><div v-if="loading" class="loading"><div class="spinner"></div></div><div v-else class="rubric-layout"><aside class="card rubric-list"><button v-for="r in rubrics" :key="r.id" :title="r.name" :class="{active:selectedId===r.id}" @click="select(r.id)"><b>{{r.name}}</b><small>{{locale.t('Version')}} {{r.version}} · {{r.criteria.length}} {{locale.t('domains')}} · {{locale.t(r.status)}}</small><span class="rubric-list__description">{{r.description}}</span></button><button v-if="selectedId==='new'" class="active"><b>{{locale.t('New rubric')}}</b><small>{{locale.t('Unsaved draft')}}</small></button><div v-if="!rubrics.length&&selectedId!=='new'" class="empty"><p>No rubrics available.</p></div></aside><main v-if="working"><section class="card card--padded rubric-head"><div><div class="field"><label>Rubric name</label><input v-model="working.name" class="input" required></div><div class="field rubric-description"><label>Description</label><textarea v-model="working.description" class="textarea"></textarea></div></div><div><StatusPill :value="working.status"/><div class="weight-total" :class="{bad:total!==100}"><span>Total weight</span><b>{{total}}%</b><small>{{total===100?'Ready to save':'Must equal 100%'}}</small></div></div></section><section class="criteria"><article v-for="(criterion,index) in working.criteria" :key="criterion.id" class="card criterion"><div class="criterion__head"><span>{{String(index+1).padStart(2,'0')}}</span><div class="field"><label>Assessment domain</label><input v-model="criterion.name" class="input"></div><div class="field"><label>Weight %</label><input v-model.number="criterion.weight" class="input" type="number" min="0" max="100"></div><label class="critical"><input v-model="criterion.critical" type="checkbox">Safety critical</label><button class="button button--link" @click="remove(index)"><Trash2 :size="16"/></button></div><div class="field"><label>Description</label><textarea v-model="criterion.description" class="textarea"></textarea></div><div class="field red-flags-field"><label>Red flag fact IDs</label><input class="input" :value="criterion.redFlagIds?.join(', ')||''" :aria-label="`Red flag fact IDs for ${criterion.name}`" placeholder="e.g. chest.hpi.01, chest.assoc.02" @input="updateRedFlagIds(criterion,$event)"><small>Comma-separated. IDs must match stable fact or red flag IDs in the linked case.</small></div><details><summary>Behaviour anchors (0–3)</summary><div v-for="anchor in criterion.anchors" :key="anchor.score" class="anchor"><b>{{anchor.score}}</b><input v-model="anchor.label" class="input" :aria-label="`Score ${anchor.score} label`"><input v-model="anchor.description" class="input" :aria-label="`Score ${anchor.score} description`"></div></details></article></section><button class="button button--secondary" @click="add"><Plus :size="16"/>Add assessment domain</button></main></div></div></template>
<style scoped>.rubric-actions{display:flex;gap:8px;flex-wrap:wrap}.rubric-layout{display:grid;grid-template-columns:240px 1fr;gap:18px}.rubric-list{padding:8px;height:fit-content}.rubric-list button{border:0;background:transparent;width:100%;text-align:left;padding:13px;border-radius:9px;display:grid;gap:3px;cursor:pointer}.rubric-list button.active{background:var(--green-soft);color:var(--green-dark)}.rubric-list b{font-size:12px}.rubric-list small{font-size:9px;color:var(--muted)}.rubric-head{display:grid;grid-template-columns:1fr auto;gap:20px;align-items:end}.rubric-head>div:last-child{display:grid;gap:10px;justify-items:end}.rubric-description,.red-flags-field{margin-top:11px}.weight-total{min-width:125px;display:grid;padding:9px 14px;border-radius:9px;background:var(--green-soft);color:var(--green)}.weight-total span,.weight-total small{font-size:9px}.weight-total b{font-size:20px}.weight-total.bad{background:var(--amber-soft);color:var(--amber)}.criteria{display:grid;gap:12px;margin:13px 0}.criterion{padding:19px}.criterion__head{display:grid;grid-template-columns:32px 1fr 110px auto auto;gap:10px;align-items:end;margin-bottom:13px}.criterion__head>span{align-self:center;color:var(--sage);font:600 19px 'Source Serif 4',serif}.critical{align-self:center;font-size:10px;white-space:nowrap}.criterion details{margin-top:15px;border-top:1px solid var(--line);padding-top:12px}.criterion summary{cursor:pointer;color:var(--green);font-weight:700;font-size:11px}.anchor{display:grid;grid-template-columns:25px 160px 1fr;gap:8px;align-items:center;margin-top:8px}.anchor b{color:var(--green)}@media(max-width:850px){.rubric-layout{grid-template-columns:1fr}.criterion__head{grid-template-columns:30px 1fr 90px}.critical{grid-column:2}.anchor{grid-template-columns:25px 1fr}.anchor input:last-child{grid-column:2}.rubric-head{grid-template-columns:1fr}.rubric-actions{width:100%}.rubric-actions .button{flex:1}}</style>
